package io.scenariomesh.coordinator;import io.scenariomesh.core.*;import io.scenariomesh.core.Domain.*;import java.util.*;import java.util.concurrent.*;
public final class Coordinator{private final Ports.SchedulingStrategy scheduler;private final Ports.ScenarioExecutionAdapter executor;public Coordinator(Ports.SchedulingStrategy scheduler,Ports.ScenarioExecutionAdapter executor){this.scheduler=scheduler;this.executor=executor;}public List<ExecutionResult> execute(RunId run,List<ScenarioTask> tasks,List<WorkerId> workers)throws InterruptedException{scheduler.load(tasks);var results=new CopyOnWriteArrayList<ExecutionResult>();var pool=Executors.newFixedThreadPool(workers.size());try{for(var w:workers)pool.submit(()->{for(;;){ScenarioTask t=scheduler.nextEligible(x->true);if(t==null)return;try{results.add(executor.execute(t,new Ports.ExecutionContext(run,w,1,Map.of())));}catch(Exception e){results.add(new ExecutionResult(t.id(),ResultStatus.INFRASTRUCTURE_FAILURE,java.time.Duration.ZERO,w,1,java.time.Instant.now(),java.time.Instant.now(),e.getMessage()));}}});}finally{pool.shutdown();pool.awaitTermination(1,TimeUnit.HOURS);}return List.copyOf(results);}}
